typedef unsigned int nlUint32;
typedef unsigned int nslSoundId;

enum nslSoundStatusEnum {
  NSL_SOUNDSTATUS_INVALID = 0
};

enum {
  NSL_SLOT_MASK = 0x000003ff,
  NSL_ID_INCREMENT = 0x00000400,
  NSL_GLOBAL_EMITTER_ID = 0,
  GAS_RPC_STOP_INSTANCE = 0x10b0
};

#define NSL_GET_SLOT_FROM_ID(x) ((x) & NSL_SLOT_MASK)
#define GAS_INVALID_ID -1

template<class T> class fifo_queue {
  T *queue;
  short queue_max;
  short start;
  short end;
  short count;
public:
  short find(const T& index_to_find, short remove_flag);
};

struct nslSound {
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  nlUint32 gasInstanceId;
  int pauseCount;
  int dampenCount;
  nslSoundId myId;
  unsigned int mySource;
  unsigned int myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslEmitter {
  char fields[44];
  fifo_queue<nslSoundId> emittedSounds;
  char tail[8];
};

struct nslSystem {
  char beforeSounds[0xc040];
  nslSound soundSlots[256];
  nslEmitter emitterSlots[256];
  nlUint32 sourceSlotsUsedCount;
  nlUint32 soundSlotsUsedCount;
  nlUint32 emitterSlotsUsedCount;
  int firstInit;
  int initialized;
  nlUint32 numBanks;
  fifo_queue<nslSoundId> queuedSounds;
  char state[28];
  bool on;
};

extern nslSystem nsl;
extern const char init_error[];
extern void nslFatal(const char *, ...);
extern nslSoundStatusEnum nslGetSoundStatus(nslSoundId);
extern int nslPs2GasRpc(int, const char *, int, int, int, int);
extern void _nslClearSoundSlot(nlUint32, bool);

asm(".equ nsl,0x0049B5F0");
asm(".equ init_error,0x0051BF80");
asm(".equ nslFatal__FPCce,0x00391420");
asm(".equ nslGetSoundStatus__FUi,0x0038DBA0");
asm(".equ nslPs2GasRpc__FiPCciiii,0x00391AC0");
asm(".equ _nslClearSoundSlot__FUib,0x00390FC8");
asm(".equ find__t10fifo_queue1ZUiRCUis,0x0038F0A8");

#define ASSERT_NSL_INITIALIZED() \
  do { if (!(nsl.initialized == 1)) nslFatal(init_error); } while (0)

void nslStopSound( nslSoundId soundToStop )
{
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();

  if ( nslGetSoundStatus( soundToStop ) != NSL_SOUNDSTATUS_INVALID )
  {
    if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToStop)].gasInstanceId != (nlUint32)GAS_INVALID_ID)
      nslPs2GasRpc(GAS_RPC_STOP_INSTANCE, "", nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToStop)].gasInstanceId, 0, 0, 0);
    nsl.queuedSounds.find(soundToStop, true);

    if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToStop)].myEmitter != NSL_GLOBAL_EMITTER_ID)
      nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToStop)].myEmitter)].emittedSounds.find(soundToStop, true);

    _nslClearSoundSlot(NSL_GET_SLOT_FROM_ID(soundToStop), false);
    nsl.soundSlotsUsedCount--;
    nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToStop)].myId += NSL_ID_INCREMENT;
  }
}
